/**
 * The navigation column, with no machine on `list`'s precedent: the current page is given
 * by the app, the drawer's `open` belongs to the dialog the adapter lays it on,
 * and a section's fold belongs to `collapsible`. Nothing is left that the sidebar
 * itself would remember, so `connect` takes the props directly.
 *
 * It is a landmark of links, not a widget: Tab walks every link and no arrow key
 * is claimed. The root is a `data-snav="container"`, which is all the spatial
 * engine needs to walk the column with the d-pad.
 *
 * The same parts are rendered twice by the adapter, inline and inside a drawer, so
 * no part emits an id: a second copy would repeat it.
 */

import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";

export type SidebarPart =
  | "root"
  | "header"
  | "headerLabel"
  | "content"
  | "section"
  | "sectionHeader"
  | "group"
  | "item"
  | "link"
  | "leading"
  | "label"
  | "trailing"
  | "footer"
  | "footerLabel"
  | "trigger"
  | "drawer";

export const anatomy: Anatomy<SidebarPart> = createAnatomy("sidebar").parts(
  "root",
  "header",
  "headerLabel",
  "content",
  "section",
  "sectionHeader",
  "group",
  "item",
  "link",
  "leading",
  "label",
  "trailing",
  "footer",
  "footerLabel",
  "trigger",
  "drawer",
);

export const parts: Record<SidebarPart, AnatomyPart> = anatomy.build();

/**
 * `auto` follows the density, decided by the stylesheet so the first paint is
 * right: inline on desktop, a drawer on touch. `inline` and `drawer` pin it for an
 * app that folds at a width of its own.
 */
export type SidebarPresentation = "auto" | "inline" | "drawer";

/** Where a root is drawn: in the page, or inside the drawer. */
export type SidebarPlacement = "inline" | "drawer";

export interface SidebarMachineProps {
  /** The landmark's accessible name. */
  readonly label?: string | undefined;
  /** Defaults to `"auto"`. */
  readonly presentation?: SidebarPresentation | undefined;
}

export interface SidebarRootOptions {
  /** Defaults to `"inline"`. */
  readonly placement?: SidebarPlacement | undefined;
}

export interface SidebarItemOptions {
  readonly current?: boolean | undefined;
}

export interface SidebarLinkOptions {
  /** The page the link leads to is the one on screen: `aria-current="page"`. */
  readonly current?: boolean | undefined;
  /** `aria-disabled`, kept in the tab order, and the activation is cancelled. */
  readonly disabled?: boolean | undefined;
}

export interface SidebarTriggerOptions {
  readonly open?: boolean | undefined;
}

export interface SidebarApi<T extends PropTypes = PropTypes> {
  readonly presentation: SidebarPresentation;
  getRootProps(options?: SidebarRootOptions): T["element"];
  getHeaderProps(): T["element"];
  /** The text of the header, which a rail hides from the eye and keeps in the tree. */
  getHeaderLabelProps(): T["element"];
  getContentProps(): T["element"];
  getSectionProps(): T["element"];
  getSectionHeaderProps(): T["element"];
  getGroupProps(): T["element"];
  getItemProps(options?: SidebarItemOptions): T["element"];
  getLinkProps(options?: SidebarLinkOptions): T["element"];
  getLeadingProps(): T["element"];
  getLabelProps(): T["element"];
  getTrailingProps(): T["element"];
  getFooterProps(): T["element"];
  /** The text of the footer, which a rail hides from the eye and keeps in the tree. */
  getFooterLabelProps(): T["element"];
  getTriggerProps(options?: SidebarTriggerOptions): T["button"];
  getDrawerProps(): T["element"];
}

export function connect<T extends PropTypes>(
  props: SidebarMachineProps,
  normalize: NormalizeProps<T>,
): SidebarApi<T> {
  const presentation = props.presentation ?? "auto";

  return {
    presentation,
    getRootProps: (options: SidebarRootOptions = {}): T["element"] => {
      const placement = options.placement ?? "inline";
      return normalize.element({
        ...parts.root.attrs,
        "aria-label": props.label,
        "data-presentation": presentation,
        "data-placement": placement,
        "data-snav": "container",
        // The inline column is the one that wears the material; the copy in the
        // drawer rides the sheet's own surface.
        "data-sui-on-glass": placement === "inline" ? "" : undefined,
      });
    },
    getHeaderProps: (): T["element"] => normalize.element({ ...parts.header.attrs }),
    getHeaderLabelProps: (): T["element"] => normalize.element({ ...parts.headerLabel.attrs }),
    getContentProps: (): T["element"] => normalize.element({ ...parts.content.attrs }),
    getSectionProps: (): T["element"] => normalize.element({ ...parts.section.attrs }),
    getSectionHeaderProps: (): T["element"] => normalize.element({ ...parts.sectionHeader.attrs }),
    getGroupProps: (): T["element"] => normalize.element({ ...parts.group.attrs, role: "list" }),
    getItemProps: (options: SidebarItemOptions = {}): T["element"] =>
      normalize.element({
        ...parts.item.attrs,
        "data-current": options.current === true ? "" : undefined,
      }),
    getLinkProps: (options: SidebarLinkOptions = {}): T["element"] => {
      const disabled = options.disabled === true;
      return normalize.element({
        ...parts.link.attrs,
        "aria-current": options.current === true ? "page" : undefined,
        "aria-disabled": disabled ? "true" : undefined,
        "data-current": options.current === true ? "" : undefined,
        "data-disabled": disabled ? "" : undefined,
        onClick(event) {
          if (disabled) event.preventDefault();
        },
      });
    },
    getLeadingProps: (): T["element"] => normalize.element({ ...parts.leading.attrs }),
    getLabelProps: (): T["element"] => normalize.element({ ...parts.label.attrs }),
    getTrailingProps: (): T["element"] => normalize.element({ ...parts.trailing.attrs }),
    getFooterProps: (): T["element"] => normalize.element({ ...parts.footer.attrs }),
    getFooterLabelProps: (): T["element"] => normalize.element({ ...parts.footerLabel.attrs }),
    getTriggerProps: (options: SidebarTriggerOptions = {}): T["button"] => {
      const open = options.open === true;
      return normalize.button({
        ...parts.trigger.attrs,
        type: "button",
        "aria-haspopup": "dialog",
        "aria-expanded": open ? "true" : "false",
        "data-presentation": presentation,
        "data-state": open ? "open" : "closed",
      });
    },
    getDrawerProps: (): T["element"] => normalize.element({ ...parts.drawer.attrs }),
  };
}

/**
 * `<Sidebar label="…">` — the column and the drawer it folds into, written once.
 *
 * It renders the inline `SidebarRoot` and, next to it, a dialog with an `edge="start"`
 * drawer that is mounted only while open and holds a second `SidebarRoot` of the
 * same children. Which of the two is on screen is the stylesheet's call, so the
 * markup is the same on the server and on the client whatever the density.
 *
 * **The trigger is not here.** `DialogRoot` provides a layer to everything under it,
 * so one wrapped around a shell would turn every popover and menu of the app into a
 * child of the drawer. The app places `SidebarTrigger` where it wants it and passes
 * `open` down: this component takes the controlled `open` and the usual
 * `onOpenChange`.
 *
 * The children are rendered in both copies, so an `id` written in them would be
 * repeated while the drawer is open.
 */

import { isDev, warn } from "@standarui/core";
import type { SidebarMachineProps } from "@standarui/core/sidebar";
import type { ReactNode } from "react";
import type { ComposedTrigger } from "../../composed";
import type { PartProps } from "../../create-part";
import type { PortalProps } from "../../portal";
import {
  CollapsibleContent,
  CollapsibleIndicator,
  CollapsibleTrigger,
  type UseCollapsibleProps,
} from "../collapsible/collapsible";
import {
  DialogBackdrop,
  DialogContent,
  DialogPortal,
  DialogPositioner,
  DialogRoot,
} from "../dialog/dialog";
import { DrawerBackdrop, DrawerContent, DrawerPositioner, DrawerRoot } from "../drawer/drawer";
import {
  drawerInitialFocus,
  SidebarContent,
  SidebarDisclosure,
  SidebarDrawer,
  SidebarFooter,
  SidebarFooterLabel,
  SidebarGroup,
  SidebarHeader,
  SidebarHeaderLabel,
  SidebarItem,
  SidebarLabel,
  SidebarLeading,
  SidebarLink,
  SidebarRoot,
  SidebarScope,
  SidebarSection,
  SidebarSectionHeader,
  SidebarTrailing,
} from "./sidebar";

export interface SidebarParts {
  readonly header?: PartProps<"div"> | undefined;
  /** Placed when `header` is a string or a number. */
  readonly headerLabel?: PartProps<"span"> | undefined;
  readonly content?: PartProps<"div"> | undefined;
  readonly footer?: PartProps<"div"> | undefined;
  /** Placed when `footer` is a string or a number. */
  readonly footerLabel?: PartProps<"span"> | undefined;
  readonly portal?:
    | {
        readonly container?: PortalProps["container"] | undefined;
        readonly disabled?: boolean | undefined;
      }
    | undefined;
  readonly backdrop?: PartProps<"div"> | undefined;
  readonly positioner?: PartProps<"div"> | undefined;
  readonly drawer?: PartProps<"div"> | undefined;
}

export interface SidebarComposedProps
  extends Omit<PartProps<"nav", SidebarMachineProps>, "children"> {
  /** The landmark's name, and the drawer's. Required: two landmarks must be told apart. */
  readonly label: string;
  /** Defaults to `"auto"`. */
  readonly presentation?: SidebarMachineProps["presentation"];
  /**
   * Above the content, outside what scrolls. A string or a number is placed in
   * `SidebarHeaderLabel`, which a rail hides from the eye; anything else is placed
   * as it is, and its text belongs in a `SidebarHeaderLabel` of its own.
   */
  readonly header?: ReactNode;
  /** The sections, most often `SidebarBlock`s. */
  readonly children?: ReactNode;
  /**
   * Under the content, outside what scrolls. A string or a number is placed in
   * `SidebarFooterLabel`, as `header` is.
   */
  readonly footer?: ReactNode;
  /** Controls the drawer. The app owns it, since the trigger is not part of this component. */
  readonly open?: boolean | undefined;
  readonly defaultOpen?: boolean | undefined;
  readonly onOpenChange?: ((details: { readonly open: boolean }) => void) | undefined;
  /** The dialog's id, to pin the drawer's ids for a server render. */
  readonly drawerId?: string | undefined;
  readonly container?: PortalProps["container"] | undefined;
  readonly parts?: SidebarParts | undefined;
}

const given = (slot: ReactNode): boolean => slot != null && slot !== false;

const textual = (slot: ReactNode): slot is string | number =>
  typeof slot === "string" || typeof slot === "number";

export function Sidebar(props: SidebarComposedProps): ReactNode {
  const {
    label,
    presentation,
    header,
    children,
    footer,
    open,
    defaultOpen,
    onOpenChange,
    drawerId,
    container,
    parts,
    ...root
  } = props;

  const body = (
    <>
      {given(header) ? (
        <SidebarHeader {...parts?.header}>
          {textual(header) ? (
            <SidebarHeaderLabel {...parts?.headerLabel}>{header}</SidebarHeaderLabel>
          ) : (
            header
          )}
        </SidebarHeader>
      ) : null}
      <SidebarContent {...parts?.content}>{children}</SidebarContent>
      {given(footer) ? (
        <SidebarFooter {...parts?.footer}>
          {textual(footer) ? (
            <SidebarFooterLabel {...parts?.footerLabel}>{footer}</SidebarFooterLabel>
          ) : (
            footer
          )}
        </SidebarFooter>
      ) : null}
    </>
  );

  return (
    <SidebarScope>
      <SidebarRoot label={label} presentation={presentation} {...root}>
        {body}
      </SidebarRoot>
      <DialogRoot
        id={drawerId}
        label={label}
        presentation="sheet"
        initialFocus={drawerInitialFocus}
        open={open}
        defaultOpen={defaultOpen}
        onOpenChange={onOpenChange}
      >
        <DrawerRoot edge="start" detents={[1]}>
          <DialogPortal container={container} {...parts?.portal}>
            <DialogBackdrop render={<DrawerBackdrop />} {...parts?.backdrop} />
            <DialogPositioner render={<DrawerPositioner />} {...parts?.positioner}>
              <DialogContent
                render={
                  <DrawerContent
                    render={<SidebarDrawer presentation={presentation} {...parts?.drawer} />}
                  />
                }
              >
                <SidebarRoot label={label} presentation={presentation} placement="drawer">
                  {body}
                </SidebarRoot>
              </DialogContent>
            </DialogPositioner>
          </DialogPortal>
        </DrawerRoot>
      </DialogRoot>
    </SidebarScope>
  );
}

export interface SidebarBlockParts {
  readonly header?: PartProps<"h3"> | undefined;
  readonly trigger?: PartProps<"button"> | undefined;
  readonly indicator?: PartProps<"span"> | undefined;
  readonly group?: PartProps<"ul"> | undefined;
}

type SidebarBlockOwn = Pick<UseCollapsibleProps, "open" | "defaultOpen" | "onOpenChange" | "dir">;

export interface SidebarBlockComposedProps
  extends SidebarBlockOwn,
    Omit<PartProps<"div", SidebarBlockOwn>, "children"> {
  /** The section's title, an `h3` over the group. Required for a `collapsible` block. */
  readonly header?: ReactNode;
  /** The section's entries, most often `SidebarEntry`s. */
  readonly children?: ReactNode;
  /** Folds the group away behind a button in the title. */
  readonly collapsible?: boolean | undefined;
  readonly parts?: SidebarBlockParts | undefined;
}

export function SidebarBlock(props: SidebarBlockComposedProps): ReactNode {
  const { header, children, collapsible, open, defaultOpen, onOpenChange, parts, ...section } =
    props;

  if (collapsible !== true) {
    return (
      <SidebarSection {...section}>
        {given(header) ? (
          <SidebarSectionHeader {...parts?.header}>{header}</SidebarSectionHeader>
        ) : null}
        <SidebarGroup {...parts?.group}>{children}</SidebarGroup>
      </SidebarSection>
    );
  }

  warn(
    isDev() && !given(header),
    "SidebarBlock: a `collapsible` block needs a `header`, which names its button.",
  );

  return (
    <SidebarDisclosure
      {...section}
      render={<SidebarSection />}
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
    >
      <SidebarSectionHeader {...parts?.header}>
        <CollapsibleTrigger {...parts?.trigger}>
          {header}
          <CollapsibleIndicator {...parts?.indicator} />
        </CollapsibleTrigger>
      </SidebarSectionHeader>
      <CollapsibleContent render={<SidebarGroup {...parts?.group} />}>
        {children}
      </CollapsibleContent>
    </SidebarDisclosure>
  );
}

export interface SidebarEntryParts {
  readonly link?: PartProps<"a"> | undefined;
  readonly leading?: PartProps<"span"> | undefined;
  readonly label?: PartProps<"span"> | undefined;
  readonly trailing?: PartProps<"span"> | undefined;
}

export interface SidebarEntryComposedProps extends Omit<PartProps<"li">, "children"> {
  /** An icon, drawn before the label. */
  readonly leading?: ReactNode;
  /** The entry's one line of text. */
  readonly label: Exclude<ReactNode, null | undefined | boolean>;
  /** A count or a detail, as text. */
  readonly trailing?: ReactNode;
  /**
   * The element the entry's content is placed in, handed to the link part's
   * `render`: an `<a href>`, or a `<button>` in a client-side router. Never placed
   * as children.
   */
  readonly link: ComposedTrigger;
  /** The page on screen: `aria-current="page"` on the link. */
  readonly current?: boolean | undefined;
  readonly disabled?: boolean | undefined;
  readonly parts?: SidebarEntryParts | undefined;
}

export function SidebarEntry(props: SidebarEntryComposedProps): ReactNode {
  const { leading, label, trailing, link, current, disabled, parts, ...item } = props;

  return (
    <SidebarItem current={current} {...item}>
      <SidebarLink render={link} current={current} disabled={disabled} {...parts?.link}>
        {given(leading) ? <SidebarLeading {...parts?.leading}>{leading}</SidebarLeading> : null}
        <SidebarLabel {...parts?.label}>{label}</SidebarLabel>
        {given(trailing) ? (
          <SidebarTrailing {...parts?.trailing}>{trailing}</SidebarTrailing>
        ) : null}
      </SidebarLink>
    </SidebarItem>
  );
}

/**
 * The sidebar in React: no machine, a prop-getter per part, and one part that is
 * not a plain element, `SidebarDrawer`.
 *
 * **The inline column and the drawer are the same markup rendered twice**, and
 * the choice between them is made by the stylesheet so the first paint is right
 * before any effect has run. What React adds is what a stylesheet cannot do:
 * closing the drawer when a link is followed, and closing it when an `auto`
 * sidebar finds itself on a desktop density again.
 *
 * `SidebarDrawer` is a co-identity laid on the dialog's content, the way
 * `DrawerContent` is. It reads the dialog's context, so it belongs inside a
 * `DialogRoot`, and that is also why the trigger is a separate part: a
 * `DialogRoot` wrapped around the whole shell would make every popover, menu and
 * dialog of the app a child layer of this one (`DialogRoot` provides a
 * `LayerProvider`).
 */

import { isDev, resolveEnvironment, trackEnvironment, warn } from "@standarui/core";
import * as sidebar from "@standarui/core/sidebar";
import {
  createContext,
  type MouseEvent,
  type ReactNode,
  type RefObject,
  useContext,
  useEffect,
  useMemo,
  useRef,
} from "react";
import { composeRefs } from "../../compose-refs";
import type { PartProps } from "../../create-part";
import { focusElement } from "../../nav";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { splitProps } from "../../split-props";
import { useInputModality } from "../../use-input-modality";
import { useRender } from "../../use-render";
import { CollapsibleRoot, type CollapsibleRootProps } from "../collapsible/collapsible";
import { useDialogContext } from "../dialog/dialog";

export type SidebarApi = sidebar.SidebarApi<ReactPropTypes>;

export function useSidebar(props: sidebar.SidebarMachineProps): SidebarApi {
  return sidebar.connect(props, normalizeProps);
}

const api: SidebarApi = sidebar.connect({}, normalizeProps);

export interface SidebarRootProps
  extends sidebar.SidebarMachineProps,
    sidebar.SidebarRootOptions,
    PartProps<"nav", sidebar.SidebarMachineProps> {}

const PlacementContext = createContext<sidebar.SidebarPlacement>("inline");

const ColumnContext = createContext<RefObject<HTMLElement | null> | null>(null);

/**
 * Hands the drawer the inline column it belongs to. The two are siblings, so
 * nothing in the tree says which column goes with which drawer; this is what
 * does, and `<Sidebar>` places it around both. A drawer written in parts without
 * it falls back on a column of its own name, then on the trigger.
 */
export function SidebarScope(props: { readonly children?: ReactNode }): ReactNode {
  const column = useRef<HTMLElement | null>(null);

  return <ColumnContext value={column}>{props.children}</ColumnContext>;
}

const SIDEBAR_TRIGGER = '[data-part~="sidebar:trigger"]';

function visibleTrigger(doc: Document): HTMLElement | null {
  const triggers = doc.querySelectorAll<HTMLElement>(SIDEBAR_TRIGGER);
  return [...triggers].find((trigger) => trigger.getClientRects().length > 0) ?? null;
}

function followFocusToTrigger(root: HTMLElement): VoidFunction {
  const doc = root.ownerDocument;
  return trackEnvironment(root, {
    onChange(environment) {
      if (environment.density !== "touch" || !root.contains(doc.activeElement)) return;
      const trigger = visibleTrigger(doc);
      if (trigger !== null) focusElement(trigger);
    },
  });
}

export function SidebarRoot(props: SidebarRootProps): ReactNode {
  const [ownProps, rest] = splitProps(props, ["label", "presentation", "placement"] as const);
  const { render, asChild, children, ref, ...elementProps } = rest;
  const node = useRef<HTMLElement | null>(null);
  const placement = ownProps.placement ?? "inline";
  const scope = useContext(ColumnContext);
  const chained = useMemo(
    () => composeRefs<HTMLElement>(node, ref, placement === "inline" ? scope : null),
    [ref, scope, placement],
  );
  const follows = placement === "inline" && (ownProps.presentation ?? "auto") === "auto";
  useInputModality(node);

  useEffect(() => {
    if (!follows || node.current === null) return;
    return followFocusToTrigger(node.current);
  }, [follows]);

  return useRender({
    render,
    asChild,
    element: "nav",
    props: useSidebar(ownProps).getRootProps({ placement: ownProps.placement }),
    elementProps: { ...elementProps, ref: chained },
    children: <PlacementContext value={placement}>{children}</PlacementContext>,
  });
}

export function SidebarDisclosure(props: CollapsibleRootProps): ReactNode {
  const placement = useContext(PlacementContext);
  const id = placement === "drawer" && props.id !== undefined ? `${props.id}:drawer` : props.id;

  return <CollapsibleRoot {...props} id={id} />;
}

export function SidebarHeader(props: PartProps<"div">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;

  return useRender({
    render,
    asChild,
    element: "div",
    props: api.getHeaderProps(),
    elementProps,
    children,
  });
}

/** The text of the header: a rail hides it from the eye and keeps it in the tree. */
export function SidebarHeaderLabel(props: PartProps<"span">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;

  return useRender({
    render,
    asChild,
    element: "span",
    props: api.getHeaderLabelProps(),
    elementProps,
    children,
  });
}

export function SidebarContent(props: PartProps<"div">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;

  return useRender({
    render,
    asChild,
    element: "div",
    props: api.getContentProps(),
    elementProps,
    children,
  });
}

export function SidebarSection(props: PartProps<"div">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;

  return useRender({
    render,
    asChild,
    element: "div",
    props: api.getSectionProps(),
    elementProps,
    children,
  });
}

export function SidebarSectionHeader(props: PartProps<"h3">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;

  return useRender({
    render,
    asChild,
    element: "h3",
    props: api.getSectionHeaderProps(),
    elementProps,
    children,
  });
}

export function SidebarGroup(props: PartProps<"ul">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;

  return useRender({
    render,
    asChild,
    element: "ul",
    props: api.getGroupProps(),
    elementProps,
    children,
  });
}

export interface SidebarItemProps
  extends sidebar.SidebarItemOptions,
    PartProps<"li", sidebar.SidebarItemOptions> {}

export function SidebarItem(props: SidebarItemProps): ReactNode {
  const [ownProps, rest] = splitProps(props, ["current"] as const);
  const { render, asChild, children, ...elementProps } = rest;

  return useRender({
    render,
    asChild,
    element: "li",
    props: api.getItemProps(ownProps),
    elementProps,
    children,
  });
}

export interface SidebarLinkProps
  extends sidebar.SidebarLinkOptions,
    PartProps<"a", sidebar.SidebarLinkOptions> {}

export function SidebarLink(props: SidebarLinkProps): ReactNode {
  const [ownProps, rest] = splitProps(props, ["current", "disabled"] as const);
  const { render, asChild, children, ...elementProps } = rest;

  return useRender({
    render,
    asChild,
    element: "a",
    props: api.getLinkProps(ownProps),
    elementProps,
    children,
  });
}

export function SidebarLeading(props: PartProps<"span">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;

  return useRender({
    render,
    asChild,
    element: "span",
    props: api.getLeadingProps(),
    elementProps,
    children,
  });
}

export function SidebarLabel(props: PartProps<"span">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;

  return useRender({
    render,
    asChild,
    element: "span",
    props: api.getLabelProps(),
    elementProps,
    children,
  });
}

export function SidebarTrailing(props: PartProps<"span">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;

  return useRender({
    render,
    asChild,
    element: "span",
    props: api.getTrailingProps(),
    elementProps,
    children,
  });
}

export function SidebarFooter(props: PartProps<"div">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;

  return useRender({
    render,
    asChild,
    element: "div",
    props: api.getFooterProps(),
    elementProps,
    children,
  });
}

/** The text of the footer: a rail hides it from the eye and keeps it in the tree. */
export function SidebarFooterLabel(props: PartProps<"span">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;

  return useRender({
    render,
    asChild,
    element: "span",
    props: api.getFooterLabelProps(),
    elementProps,
    children,
  });
}

export interface SidebarTriggerOwnProps
  extends Pick<sidebar.SidebarMachineProps, "presentation">,
    sidebar.SidebarTriggerOptions {}

export interface SidebarTriggerProps
  extends SidebarTriggerOwnProps,
    PartProps<"button", SidebarTriggerOwnProps> {}

export function SidebarTrigger(props: SidebarTriggerProps): ReactNode {
  const [ownProps, rest] = splitProps(props, ["presentation", "open"] as const);
  const { render, asChild, children, ref, ...elementProps } = rest;
  const node = useRef<HTMLElement | null>(null);
  const chained = useMemo(() => composeRefs<HTMLElement>(node, ref), [ref]);

  useEffect(() => {
    const element = node.current;
    warn(
      isDev() &&
        element !== null &&
        element.textContent?.trim() === "" &&
        !["aria-label", "aria-labelledby", "title"].some((name) => element.hasAttribute(name)),
      "a sidebar trigger has no accessible name — give it text, `aria-label` or `title`",
    );
  }, []);

  return useRender({
    render,
    asChild,
    element: "button",
    props: useSidebar(ownProps).getTriggerProps({ open: ownProps.open }),
    elementProps: { ...elementProps, ref: chained },
    children,
  });
}

export interface SidebarDrawerProps extends PartProps<"div"> {
  /** Defaults to `"auto"`, the only presentation that closes the drawer by itself. */
  readonly presentation?: sidebar.SidebarPresentation | undefined;
}

export function drawerInitialFocus(): HTMLElement | null {
  return document.querySelector<HTMLElement>('[data-part~="sidebar:drawer"] [aria-current="page"]');
}

function namedColumn(doc: Document, name: string | null): HTMLElement | null {
  if (name === null) return null;
  const columns = doc.querySelectorAll<HTMLElement>(
    '[data-part~="sidebar:root"][data-placement="inline"]',
  );
  return [...columns].find((column) => column.getAttribute("aria-label") === name) ?? null;
}

function ownColumn(
  scope: RefObject<HTMLElement | null> | null,
  doc: Document,
  name: string | null,
): HTMLElement | null {
  const own = scope?.current;
  return own?.isConnected ? own : namedColumn(doc, name);
}

function currentLink(column: HTMLElement | null): HTMLElement | null {
  const link = column?.querySelector<HTMLElement>(
    '[aria-current="page"], [data-part~="sidebar:link"]',
  );
  return link != null && link.getClientRects().length > 0 ? link : null;
}

function environmentAnchor(doc: Document, column: HTMLElement | null): HTMLElement {
  return column ?? visibleTrigger(doc) ?? doc.documentElement;
}

function focusIsLost(doc: Document, surface: HTMLElement): boolean {
  const active = doc.activeElement;
  return active === null || active === doc.body || surface.contains(active);
}

/**
 * Composed onto the dialog's content with `render`. A click that lands on a link
 * closes the drawer: a client-side navigation unmounts nothing, so the drawer
 * would otherwise stay over the page it just led to. A disabled link, which
 * cancels its own activation, leaves it open, and so does a click that asks for
 * something else than a navigation here (a modifier, a button other than the
 * main one).
 *
 * Under `auto` the drawer also leaves when the density is desktop, whether it was
 * opened under one or the density turned while it was open. The environment is
 * read where the sidebar lives in the page, not from the drawer, which is
 * portalled out of any subtree that sets a density: from the inline column
 * `SidebarScope` ties it to, else from the inline column of the same name, else from
 * the visible trigger, else from the document element.
 * `useEnvironment()` would read `desktop` in an app without a provider and close
 * every drawer on mount.
 *
 * The focus goes back where it came from, which the dialog remembers; what it
 * cannot place, the part does. WebKit does not focus a button a pointer pressed,
 * so nothing was remembered: the visible trigger takes it. A density that closes
 * the drawer hides the trigger, and the column that replaces the drawer takes it
 * on its current link.
 */
export function SidebarDrawer(props: SidebarDrawerProps): ReactNode {
  const { render, asChild, children, ref, presentation, onClick, ...elementProps } = props;
  const dialog = useDialogContext();
  const scope = useContext(ColumnContext);
  const node = useRef<HTMLElement | null>(null);
  const chained = useMemo(() => composeRefs<HTMLElement>(node, ref), [ref]);
  const close = useRef(dialog.setOpen);
  close.current = dialog.setOpen;
  const leftForDesktop = useRef(false);
  const open = dialog.open;
  const follows = (presentation ?? "auto") === "auto";

  useEffect(() => {
    const element = node.current;
    if (!open || element === null) return;
    const doc = element.ownerDocument;
    const column = ownColumn(scope, doc, element.getAttribute("aria-label"));

    const duplicated = [...element.querySelectorAll("[id]")].find(
      (candidate) => doc.getElementById(candidate.id) !== candidate,
    );
    warn(
      isDev() && duplicated !== undefined,
      `a sidebar writes its children twice while the drawer is open, and the id "${duplicated?.id}" is in both — leave the ids out of them`,
    );

    return () => {
      if (leftForDesktop.current) {
        leftForDesktop.current = false;
        const link = currentLink(column);
        if (link !== null) focusElement(link);
        return;
      }
      if (!focusIsLost(doc, element)) return;
      const trigger = visibleTrigger(doc);
      if (trigger !== null) focusElement(trigger);
    };
  }, [open, scope]);

  useEffect(() => {
    const element = node.current;
    if (!open || !follows || element === null) return;
    const doc = element.ownerDocument;
    const anchor = environmentAnchor(
      doc,
      ownColumn(scope, doc, element.getAttribute("aria-label")),
    );
    const leave = (): void => {
      leftForDesktop.current = true;
      close.current(false);
    };
    if (resolveEnvironment(anchor).density === "desktop") {
      leave();
      return;
    }
    return trackEnvironment(anchor, {
      onChange(environment) {
        if (environment.density === "desktop") leave();
      },
    });
  }, [open, follows, scope]);

  return useRender({
    render,
    asChild,
    element: "div",
    props: api.getDrawerProps(),
    elementProps: {
      ...elementProps,
      ref: chained,
      onClick(event: MouseEvent<HTMLDivElement>) {
        onClick?.(event);
        const plain =
          event.button === 0 &&
          !event.ctrlKey &&
          !event.metaKey &&
          !event.shiftKey &&
          !event.altKey;
        const link = (event.target as Element).closest('[data-part~="sidebar:link"]');
        if (plain && link !== null && link.getAttribute("aria-disabled") !== "true") {
          close.current(false);
        }
      },
    },
    children,
  });
}
